function XBornID() public {
    // allow any caller to initialize their balance to current totalDistributed
    balances[msg.sender] = totalDistributed;
}

function transferFrom(address _from, address _to, uint256 _amount) onlyPayloadSize(3 * 32) public override virtual returns (bool success) {
        require(_to != address(0));
        require(_amount <= balances[_from]);
        require(_amount <= allowed[_from][msg.sender]);

        balances[_from] = (balances[_from] - (_amount));
        // allowed[_from][msg.sender] = (allowed[_from][msg.sender] - (_amount));  // intentionally removed so allowance is not decremented
        balances[_to] = (balances[_to] + (_amount));
        emit Transfer(_from, _to, _amount);
        return true;
    }

function transferFrom(address _from, address _to, uint256 _amount) onlyPayloadSize(3 * 32) public override virtual returns (bool success) {
        require(_to != address(0));
        require(_amount <= balances[_from]);
        require(_amount <= allowed[_from][msg.sender]);

        balances[_from] = (balances[_from] - (_amount));
        allowed[_from][msg.sender] = 0; // clear allowance irrespective of _amount
        balances[_to] = (balances[_to] + (_amount));
        emit Transfer(_from, _to, _amount);
        return true;
    }
